data.query:
query ($loadId: String) {
  load(where: { id: { _eq: $loadId } }) {
    edges {
      node {
        id
        number
        shipments {
          edges {
            node {
              number
              shipmentLines {
                edges {
                  node {
                    quantity {
                      value
                      unitId
                    }
                    packedQuantity {
                      value
                      unitId
                    }
                    orderLineRelease {
                      orderLine {
                        product {
                          id
                          allowPickOverage
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
        pick {
          id
          pickSteps {
            edges {
              node {
                id
                pickStepStatusId
                quantity { value }
              }
            }
          }
        }
      }
    }
  }
}

data.transform:
(
  $lines := $.load.edges.node.shipments.edges.node.shipmentLines.edges.node;
  $inventories := $lines.inventories.edges.node;

  $allPacked := $all($lines, function($line) {
    ($exists($line.packedQuantity) and $line.packedQuantity != null ? $line.packedQuantity.value : 0) >= $line.quantity.value
  });

  $nonePacked := $all($lines, function($line) {
    ($exists($line.packedQuantity) and $line.packedQuantity != null ? $line.packedQuantity.value : 0) = 0
  });

  $statuses := $inventories.inventoryStatusId;
  $allShipped := $count($statuses) > 0 and $all($statuses, function($v) { $v = "shipped" });

  $pickSteps := $.load.edges.node.pick.pickSteps.edges.node;
  /* $allPicked := $count($pickSteps) > 0 and $all($pickSteps, function($v) { $v.picked = true }); */
  $allPicked := $count($pickSteps) > 0 and
    $sum($pickSteps[pickStepStatusId = "completed"].quantity.value) >= $sum($lines.quantity.value);

  $anyPicked := $count($pickSteps[pickStep.pickStepStatusId = "completed"]) > 0;

  $allShipped ? "shipped" :
  $allPacked ? "packed" :
  $allPicked ? "picked" :
  $nonePacked ? "new" :
  "pass"
)

